const curated = new Set(operators.map((operator) => operator[0]));
for (const row of operatorArchive) {
  const [id, name, role, stars, faction] = row;
  if (curated.has(name)) continue;
  curated.add(name);
  operators.push([name, role, stars, faction, "", "#aabbd4"]);
  profiles[name] = [id, ...roleTips[role]];
}

export function portrait(name) {
  const id = archiveByName.get(name)?.[0];
  return id
    ? "portraits/" + id + ".webp?v=2"
    : "operators/" + profiles[name][0] + ".webp";
}
